import {fleetScoreMarkup} from './fleet-score.js';
import {MOTION_PATTERNS,SHOW_STYLES} from './fleet-effects.js';
import {extraEffectsMarkup,effectSummary} from './fleet-effects-ui.js';
import {fleetHelp} from './fleet-help.js';
import {PROGRAM_SHAPES,PROGRAM_FIELDS,FIELD_FORMULAS} from './swarm-program.js';
import {COMMANDER_PRESETS} from './commander-presets.js';
import {COMMANDER_EXAMPLES} from './fleet-commander-core.js';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(entries,value)=>Object.entries(entries).map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
export const adminFleetAccess=()=>'<details class="adminFleetAccess"><summary>Advanced / admin tools</summary><p>Optional live-world tests.</p><button data-nav="adminFleet">IN-GAME FLEET TEST / UP TO 2,000</button></details>';
export function renderAdminFleet({config,started,active,stats,notice='',fleets=[],metronome=false}){
 const p=config.program.settings,select=(key,label,entries)=>`<label>${label}<select data-admin-setting="${key}">${options(entries,p[key])}</select></label>`,number=(key,label,min,max,step=1)=>`<label>${label}<input data-admin-number="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${p[key]}"></label>`;
 return `<section class="adminFleet" data-initial-pane="${p.shape==='word'?'words':p.shape==='drawing'?'drawing':'formation'}"><div class="panelTop"><div><div class="eyebrow">ADMIN / LIVE WORLD</div><h2>In-game fleet test</h2></div><button data-back>← Back</button></div><p>Temporary test aircraft in this expedition. Walk, ride or use your regular drone camera to inspect them. Terrain, buildings, hull damage and radio limits remain active.</p><div class="adminFleetStatus" data-admin-stats>${active?`${stats.active} / ${stats.total} airborne · ${stats.queued} queued · ${stats.returning} returning`:'No test aircraft spawned.'}</div>
 ${!started?'<p class="menuNotice">Start or load an expedition, then return here. <button data-nav="chapters">CHAPTERS / START</button></p>':''}
 <div class="adminFleetActions"><button class="primary" data-admin-action="spawn" ${!started?'disabled':''}>Deploy fleet & resume</button><button data-admin-action="apply" ${!active?'disabled':''}>Apply changes & resume</button><button data-admin-action="recall" ${!active?'disabled':''}>Land all at staging pads</button><button data-admin-action="launch" ${!active?'disabled':''}>Launch parked fleet</button><button data-admin-action="clear" ${!active?'disabled':''}>Remove test fleet</button></div>
 <div class="adminFleetActions">${[100,500,1000,2000].map(n=>`<button data-admin-quick-count="${n}">${n.toLocaleString()} drones</button>`).join('')}</div><div class="adminFleetGrid"><label>Test drone count<input data-admin-count type="number" min="1" max="2000" step="1" value="${config.roster.length}"></label><label>Load preset<select data-admin-preset>${options(Object.fromEntries(Object.entries(COMMANDER_PRESETS).map(([k,v])=>[k,v.name])),'none')}</select></label></div><button data-admin-action="preset">LOAD PRESET INTO CONTROLS</button>
 <nav class="fleet-task-nav" aria-label="Fleet tasks">${[['formation','Formations','Shape and movement'],['words','Word sequence','HELLO → WORLD → …'],['drawing','Draw a shape','Fly your own strokes'],['rhythm','Dance & rhythm','Tempo and choreography']].map(([key,title,description])=>`<button data-admin-pane="${key}" aria-pressed="false">${title}<small>${description}</small></button>`).join('')}</nav><button data-admin-help>Guide & shortcuts</button>
 <p class="hint">${esc(effectSummary(p))} · editor settings</p><div class="adminFleetGrid">${select('pattern','Movement',MOTION_PATTERNS)}${select('show','Choreography',SHOW_STYLES)}</div><button data-admin-action="none">NONE / CLEAR ALL EFFECTS</button><details><summary>Independent effects & variance</summary>${extraEffectsMarkup(p,true)}<div class="adminFleetGrid">${select('field','Influence 1',PROGRAM_FIELDS)}${number('strength','Influence 1 strength',0,24)}</div></details><button data-admin-script-shortcut>FLIGHT SCRIPT EDITOR</button><div data-admin-section="formation">
 <div class="adminFleetGrid">${select('shape','Formation',PROGRAM_SHAPES)}${select('origin','Anchor',{operator:'Player / rider',bike:'Bike',fixed:'Test origin',objective:'Objective ahead'})}${number('spacing','Spacing (m)',8,30)}${number('height','Height (m)',8,70)}</div>
 </div><div data-admin-section="words" hidden><h3>One fleet. Every word.</h3><p>The same aircraft travel between messages. Longer transitions give large fleets time to settle.</p><label>Messages, one per line<textarea data-admin-sequence rows="4" maxlength="288" spellcheck="false">${esc(p.sequenceWords)}</textarea></label><div class="adminFleetGrid">${number('sequenceHold','Hold each word (s)',2,30)}${number('sequenceTransition','Transition (s)',2,40)}</div><label><input data-admin-sequence-enabled type="checkbox" ${p.sequenceEnabled?'checked':''}>Play word sequence</label><label><input data-admin-sequence-loop type="checkbox" ${p.sequenceLoop?'checked':''}>Loop messages</label><button data-admin-action="sequence">USE WORD SEQUENCE</button><details><summary>Single word instead</summary><label>Word<input data-admin-word maxlength="16" value="${esc(p.word)}"></label><p>Turn off Play word sequence to use this text.</p></details></div>
 <div data-admin-section="drawing" hidden><details open><summary>Draw a formation</summary><p>Choose Drawing or Word above, edit here, then Apply & resume. Upright shapes are easiest to see from the front.</p><canvas data-admin-drawing width="640" height="280" tabindex="0" aria-label="In-game formation drawing pad. Drag to draw; arrows move the pen, Space adds a point, Enter starts a stroke."></canvas><div class="adminFleetActions"><button data-admin-action="draw">USE DRAWING FORMATION</button><button data-admin-action="undo">UNDO STROKE</button><button data-admin-action="erase">CLEAR DRAWING</button></div><output data-admin-points>${config.program.strokes.length} strokes</output><p class="hint">Keyboard: arrows move the pen, Space adds a point, Enter starts a stroke. Up to 24 strokes / 512 points.</p><div class="adminFleetGrid">${select('plane','Plane',{sky:'Upright / sky',ground:'Flat / ground'})}${number('scale','Scale',.25,3,.25)}</div><label><input type="checkbox" data-admin-trace ${p.trace?'checked':''}> Trace continuously</label></details></div>
 <div data-admin-section="rhythm" hidden><details open><summary>Dance to a beat</summary><div class="adminFleetGrid">${number('bpm','Tempo (BPM)',40,220)}${number('offset','Aircraft stagger (s)',0,2,.01)}</div><label><input data-admin-beat type="checkbox" ${p.beatSync?'checked':''}> Synchronize choreography to this beat</label><div class="adminFleetActions"><button data-admin-action="tap">TAP TEMPO</button><button data-admin-action="beat">USE BEAT DANCE</button><button data-admin-action="metronome" aria-pressed="${metronome}">${metronome?'MUTE':'ENABLE'} METRONOME</button></div><p class="hint">Tap with the music, or enter its BPM. Zero stagger moves every drone on the same beat. The optional click follows the program clock while the game runs.</p>${fleetScoreMarkup(p.song)}</details></div>
 <details data-admin-scripting><summary>Flight script / placement / formulas</summary><div class="adminFleetGrid">${number('moveX','Offset X (m)',-120,120)}${number('moveZ','Offset Z (m)',-120,120)}${number('frequency','Influence frequency',.05,3,.05)}${number('rotation','Rotation (°)',-180,180)}${number('morph','Morph time (s)',0,12)}${number('countIn','Count-in (s)',0,8)}</div><p class="hint">${esc(FIELD_FORMULAS[p.field])}</p>${['X','Y','Z'].map(k=>`<label>Δ${k} formula<input data-admin-formula="formula${k}" maxlength="240" value="${esc(p['formula'+k])}"></label>`).join('')}<label>Input mode<select data-admin-mode>${options({manual:'Hand inputs',script:'Flight script'},config.program.mode)}</select></label><label>Script example<select data-admin-example>${options(Object.fromEntries(Object.keys(COMMANDER_EXAMPLES).map(k=>[k,k])),Object.keys(COMMANDER_EXAMPLES)[0])}</select></label><button data-admin-action="example">LOAD SCRIPT EXAMPLE</button><label>Flight script<textarea data-admin-script maxlength="6000" rows="12" spellcheck="false">${esc(config.program.source)}</textarea></label><p class="hint">Select all, scouts, relays, alpha–delta, colors or drone-001. Commands: formation, assign, influence, show, beat on, bpm 120, wait, repeat. Independently stack layer 2 wave 8 0.6, layer 3 vortex 5 0.4. Clear with layer 2 none, pattern none or reset effects. Control patternSpeed, patternAmount, showSpeed, showAmount, variance, phaseVariance, speedVariance, seed and field mixes blend2–4. Load an example to start.</p></details>
 <details data-admin-archive><summary>Saved Commander fleets</summary><label>Saved fleet<select data-admin-saved><option value="">Choose a saved fleet</option>${fleets.map(f=>`<option value="${esc(f.name)}">${esc(f.name)} · ${f.roster.length} drones</option>`).join('')}</select></label><button data-admin-action="load">LOAD INTO CONTROLS</button><label>Save fleet name<input data-admin-name maxlength="48" value="${esc(config.name)}"></label><button data-admin-action="save">SAVE / REPLACE SETUP</button><p class="hint">These are the same named fleet setups as the independent Commander. Launching them here uses this game world.</p></details>
 <div class="adminFleetActions"><button data-admin-action="objective" ${!active?'disabled':''}>SET OBJECTIVE AHEAD</button><button data-admin-action="protect" ${!active?'disabled':''}>PROTECT + SCOUT</button></div><label><input data-admin-unlimited type="checkbox" ${config.options.unlimited?'checked':''}> Unlimited test-fleet battery</label><p class="hint">Pause freezes the fleet. Land returns it to reserved deployment pads, where every aircraft stays visible. Launch parked fleet reuses those same aircraft. Remove deletes the test copies. Test aircraft are excluded from campaign saves and cleared when changing expeditions, chapters or training sessions.</p><p class="adminFleetNotice" role="status">${esc(notice||'Ready. Changes take effect on Spawn or Apply.')}</p></section>`;
}
export function mountAdminDrawing(root,{strokes,onChange}){
 mountAdminNavigation(root);
 const canvas=root.querySelector('[data-admin-drawing]'),ctx=canvas?.getContext('2d');if(!ctx)return;let drawing=false,point=[0,0],keyboard=false;
 const draw=()=>{ctx.clearRect(0,0,640,280);ctx.strokeStyle='#334b50';ctx.lineWidth=1;for(let x=0;x<=640;x+=32){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,280);ctx.stroke();}for(let y=0;y<=280;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(640,y);ctx.stroke();}ctx.strokeStyle='#eee4b9';ctx.lineWidth=3;for(const stroke of strokes){ctx.beginPath();stroke.forEach(([x,y],i)=>ctx[i?'lineTo':'moveTo']((x+1)*320,(y+1)*140));ctx.stroke();}if(keyboard)ctx.strokeRect((point[0]+1)*320-5,(point[1]+1)*140-5,10,10);};
 const add=(p,start=false)=>{if(start&&strokes.length>=24||strokes.reduce((n,s)=>n+s.length,0)>=512)return false;if(start||!strokes.length)strokes.push([]);strokes.at(-1).push(p);onChange(strokes);root.querySelector('[data-admin-points]').textContent=strokes.length+' strokes · '+strokes.reduce((n,s)=>n+s.length,0)+' points';draw();return true;};
 const at=e=>{const r=canvas.getBoundingClientRect();return [Math.max(-1,Math.min(1,(e.clientX-r.left)/r.width*2-1)),Math.max(-1,Math.min(1,(e.clientY-r.top)/r.height*2-1))];};
 canvas.addEventListener('pointerdown',e=>{keyboard=false;drawing=add(at(e),true);canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{const p=at(e),last=strokes.at(-1)?.at(-1);if(drawing&&(!last||Math.hypot(p[0]-last[0],p[1]-last[1])>.03))drawing=add(p);});for(const type of ['pointerup','pointercancel'])canvas.addEventListener(type,()=>drawing=false);
 canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Enter'].includes(e.key))return;e.preventDefault();e.stopPropagation();keyboard=true;point=point.map((v,i)=>Math.max(-1,Math.min(1,v+(i===0?(e.key==='ArrowRight'?.05:e.key==='ArrowLeft'?-.05:0):(e.key==='ArrowDown'?.05:e.key==='ArrowUp'?-.05:0)))));if(e.key===' '||e.key==='Enter')add([...point],e.key==='Enter');draw();});draw();
}

let lastPane='formation';
function mountAdminNavigation(root){
 const panel=root.querySelector('.adminFleet');if(!panel)return;
 const q=s=>panel.querySelector(s),choose=(pane,change=false)=>{
  lastPane=pane;panel.querySelectorAll('[data-admin-section]').forEach(el=>el.hidden=el.dataset.adminSection!==pane);panel.querySelectorAll('[data-admin-pane]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.adminPane===pane)));
  if(change){q('[data-admin-mode]').value='manual';if(pane==='words'||pane==='drawing'){q('[data-admin-setting="shape"]').value=pane==='words'?'word':'drawing';q('[data-admin-trace]').checked=false;}else if(['word','drawing'].includes(q('[data-admin-setting="shape"]').value))q('[data-admin-setting="shape"]').value='grid';}
  if(pane==='drawing'){q('[data-admin-drawing]').closest('details').open=true;if(change)q('[data-admin-drawing]').focus();}
 };
 q('[data-admin-script-shortcut]').addEventListener('click',()=>{q('[data-admin-scripting]').open=true;q('[data-admin-mode]').value='script';q('[data-admin-script]').focus();});
 const initial=panel.dataset.initialPane;choose(['words','drawing'].includes(initial)?initial:lastPane==='rhythm'?'rhythm':'formation');
 panel.querySelectorAll('[data-admin-pane]').forEach(el=>el.addEventListener('click',()=>choose(el.dataset.adminPane,true)));
 panel.querySelectorAll('[data-admin-quick-count]').forEach(el=>el.addEventListener('click',()=>{q('[data-admin-count]').value=el.dataset.adminQuickCount;q('.adminFleetNotice').textContent='Count selected. Deploy fleet replaces the test aircraft; Apply changes keeps the current roster.';}));
 q('[data-admin-setting="shape"]').addEventListener('change',e=>{if(['word','drawing'].includes(e.target.value))choose(e.target.value==='word'?'words':'drawing');});
 q('[data-admin-help]').addEventListener('click',()=>fleetHelp(root.ownerDocument,{title:'Choose your next step',text:'Deploy creates the selected number of test aircraft. Apply changes updates the aircraft already flying. Pause freezes the show; resume to watch it. Choose a shortcut below.',actions:[{label:'Build a 2,000-aircraft fleet',run:()=>{q('[data-admin-count]').value=2000;q('[data-admin-count]').focus();}},{label:'Spell HELLO, then WORLD',run:()=>{choose('words',true);q('[data-admin-sequence]').focus();}},{label:'Draw a formation',run:()=>choose('drawing',true)},{label:'Dance to a beat',run:()=>choose('rhythm',true)},{label:'Load a saved fleet',run:()=>{q('[data-admin-archive]').open=true;q('[data-admin-saved]').focus();}}]}));
}
